Hub.UpdateCrosshairGeometry = function(self)
	if not self.Crosshair.Container then
		return;
	end
	local color = self.Theme.Accent;
	if (self.Config.Values.CrosshairColor == LUAOBFUSACTOR_DECRYPT_STR_0("\217\231\57\219\57", "\210\142\143\80\175\92")) then
		color = Color3.fromRGB(255, 255, 255);
