Hub.IsCoinBagFull = function(self)
	local isFull = false;
	local limit = self.Config.Values.AutoFarmBagLimit or 50;
	pcall(function()
		local lp = self.Services.Players.LocalPlayer;
		local pgui = lp:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\247\6\228\175\194\24\194\163\206", "\214\167\106\133"));
		local mg = pgui and pgui:FindFirstChild("MainGUI");
		if not mg then
			return;
		end
		local coinBags = mg:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\14\57\65\74", "\185\73\88\44\47\84\31")) and mg.Game:FindFirstChild("CoinBags");
		if not coinBags then
			return;
		end
		local container = coinBags:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\171\216\20\180\210\246\134\210\8", "\159\232\183\122\192\179"));
		if container then
			for _, bagFrame in ipairs(container:GetChildren()) do
				if (bagFrame:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\2\32\169\44\33", "\65\68\82\200")) and bagFrame.Visible) then
					local fullLabel = bagFrame:FindFirstChild("Full");
					if (fullLabel and fullLabel.Visible) then
						isFull = true;
						return;
					end
					for _, lbl in ipairs(bagFrame:GetDescendants()) do
						if (lbl:IsA("TextLabel") and lbl.Visible) then
							local txt = lbl.Text:match(LUAOBFUSACTOR_DECRYPT_STR_0("\109\21\118\107\134", "\30\69\48\18\64\175\175"));
							if txt then
								local num = tonumber(txt);
