Hub.GetAvailableCoins = function(self)
	local list = {};
	local cs = self.Services.CollectionService;
	local ok, tagged = pcall(function()
		return cs:GetTagged(LUAOBFUSACTOR_DECRYPT_STR_0("\211\35\22\226\13\249\63\10\237\55", "\91\144\76\127\140"));
	end);
	if (ok and (type(tagged) == "table") and (#tagged > 0)) then
		for _, v in ipairs(tagged) do
			if (v and v.Parent and v:IsA("BasePart")) then
				if (not v:GetAttribute("Collected") and not v:GetAttribute("Delete")) then
					table.insert(list, v);
				end
			end
		end
	end
	if (#list == 0) then
		local coinContainer = self.Services.Workspace:FindFirstChild("CoinContainer", true);
		if coinContainer then
			for _, c in ipairs(coinContainer:GetChildren()) do
				if (c:IsA("BasePart") and c.Parent and not c:GetAttribute("Collected")) then
					table.insert(list, c);
				elseif (c:IsA("Model") and c.Parent) then
					local p = c.PrimaryPart or c:FindFirstChildWhichIsA(LUAOBFUSACTOR_DECRYPT_STR_0("\194\9\85\36\227\187\199\196", "\176\128\104\38\65\179\218\181"));
					if (p and not p:GetAttribute("Collected")) then
						table.insert(list, p);
					end
				end
			end
		end
	end
	return list;
end;
Hub.GetTouchTargets = function(self, coin)
	local list = {};
	local seen = {};
	local function add(p)
		if (p and not seen[p] and p:IsA("BasePart") and p:FindFirstChildOfClass(LUAOBFUSACTOR_DECRYPT_STR_0("\228\203\215\22\216\240\208\20\222\215\207\28\196\208\199\7", "\117\176\164\162"))) then
			seen[p] = true;
			table.insert(list, p);
		end
	end
	add(coin);
	if coin then
		for _, v in ipairs(coin:GetChildren()) do
			add(v);
		end
		local par = coin.Parent;
		if par then
			if par:IsA("BasePart") then
				add(par);
			end
			for _, v in ipairs(par:GetChildren()) do
				add(v);
			end
		end
	end
	if ((#list == 0) and coin) then
		table.insert(list, coin);
	end
	return list;
end;
Hub.FireCoinTouch = function(self, coin)
	if (type(firetouchinterest) ~= "function") then
		return;
	end
	if (not coin or not coin.Parent) then
		return;
	end
	local now = os.clock();
	if ((now - (self.AutoFarm.LastTouch or 0)) < 0.05) then
		return;
	end
	self.AutoFarm.LastTouch = now;
	local lp = self.Services.Players.LocalPlayer;
	local char = lp and lp.Character;
	local root = char and self:GetRoot(char);
	if not root then
		return;
	end
	for _, p in ipairs(self:GetTouchTargets(coin)) do
		pcall(firetouchinterest, root, p, 0);
		pcall(firetouchinterest, root, p, 1);
	end
end;
Hub.GetMurdererHRP = function(self)
	local data = self:GetPlayerDataMap();
	if (type(data) == "table") then
		local lp = self.Services.Players.LocalPlayer;
		for name, info in pairs(data) do
			if ((type(info) == "table") and (info.Role == "Murderer") and not info.Dead and (name ~= lp.Name)) then
				local pl = self.Services.Players:FindFirstChild(name);
				local char = pl and pl.Character;
				local root = char and self:GetRoot(char);
				local hum = char and char:FindFirstChildOfClass("Humanoid");
				if (root and (not hum or (hum.Health > 0))) then
					return root;
				end
			end
		end
	end
	for _, plr in ipairs(self.Services.Players:GetPlayers()) do
		if ((plr ~= self.Services.Players.LocalPlayer) and plr.Character and plr.Character:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\175\204\12\246\223", "\25\228\162\101\144\186"))) then
			return self:GetRoot(plr.Character);
		end
	end
	return nil;
end;
Hub.PickBestCoin = function(self, pos, coins, mpos)
	if not (self.Config.Toggles.AutoFarmAvoidMurder and mpos) then
		local best, bd = nil, math.huge;
		for _, v in ipairs(coins) do
			local d = (v.Position - pos).Magnitude;
			if (d < bd) then
				bd = d;
				best = v;
			end
		end
		return best;
	end
	local AVOID_DIST = 40;
