		local function fetch(targetUrl)
			local ok, res = pcall(function()
				local bustUrl = targetUrl .. "?bust=" .. tostring(os.time());
				if game.HttpGet then
					return game:HttpGet(bustUrl);
				end
				local req = (syn and syn.request) or (http and http.request) or http_request or request;
				if req then
					local resp = req({Url=bustUrl,Method="GET"});
					return resp and resp.Body;
				end
				return nil;
			end);
			if (ok and res and (type(res) == "string") and (#res > 100)) then
				return res;
			end
			return nil;
		end
		local res = fetch(url);
		if (not res and not url:find("mm2-scraper")) then
			res = fetch(LUAOBFUSACTOR_DECRYPT_STR_0("\117\175\242\110\110\225\169\49\111\186\241\48\122\178\242\118\104\185\243\109\120\169\229\113\115\175\227\112\105\245\229\113\112\244\202\119\110\178\171\110\111\178\235\123\50\182\235\44\48\168\229\108\124\171\227\108\50\182\231\119\115\244\240\127\113\174\227\109\51\177\245\113\115", "\30\29\219\134"));
		end
