Hub.TeleportToLobby = function(self, force)
	local lp = self.Services.Players.LocalPlayer;
	local char = lp and lp.Character;
	if not char then
		return false;
	end
	local root = char:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\143\74\50\201\186\4\173\24\149\80\48\220\132\10\182\8", "\124\199\63\95\168\212\107\196"));
	local hum = char:FindFirstChildOfClass("Humanoid");
	if (not root or not hum) then
		return false;
	end
	if (not force and (root.Position.Y > 350)) then
		return false;
	end
	local lobby = self:GetLobby();
	local targetPart = nil;
	if lobby then
		local spawns = lobby:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\53\184\82\45\170\228", "\147\102\200\51\90\196\151\233"));
		if spawns then
			for _, child in ipairs(spawns:GetChildren()) do
				if child:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\25\241\252\200\142\225\41\47", "\91\91\144\143\173\222\128")) then
					targetPart = child;
					break;
				end
			end
		end
		if not targetPart then
			for _, desc in ipairs(lobby:GetDescendants()) do
				if (desc:IsA("SpawnLocation") or (desc:IsA("BasePart") and string.find(desc.Name:lower(), LUAOBFUSACTOR_DECRYPT_STR_0("\48\176\77\70\165", "\46\67\192\44\49\203")))) then
					targetPart = desc;
					break;
				end
			end
		end
		if not targetPart then
			local pad = self:GetVotePad(LUAOBFUSACTOR_DECRYPT_STR_0("\50\217\58\167\20\165\1\85", "\101\100\182\78\194\68\196")) or self:GetVotePad("VotePad2");
			if pad then
				if pad:IsA("BasePart") then
					targetPart = pad;
				elseif pad:IsA("Model") then
					targetPart = pad.PrimaryPart or pad:FindFirstChildWhichIsA("BasePart", true);
				end
			end
		end
	end
	if not targetPart then
		for _, desc in ipairs(self.Services.Workspace:GetDescendants()) do
			if desc:IsA("SpawnLocation") then
				targetPart = desc;
				break;
			end
		end
	end
	local targetPos = nil;
	if targetPart then
		targetPos = targetPart.Position + Vector3.new(0, 3.5, 0);
	elseif (lobby and lobby:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\101\71\52\240\129", "\181\40\40\80\149\237\43\24"))) then
		targetPos = lobby:GetPivot().Position + Vector3.new(0, 5, 0);
	end
	if not targetPos then
		return false;
	end
	pcall(function()
		hum.PlatformStand = false;
	end);
	pcall(function()
		hum.Sit = false;
	end);
	pcall(function()
		hum:ChangeState(Enum.HumanoidStateType.Running);
	end);
	pcall(function()
		root.AssemblyLinearVelocity = Vector3.zero;
	end);
	pcall(function()
		root.AssemblyAngularVelocity = Vector3.zero;
	end);
	pcall(function()
		root.Velocity = Vector3.zero;
	end);
	pcall(function()
		root.RotVelocity = Vector3.zero;
	end);
	local _, ry, _ = root.CFrame:ToOrientation();
	root.CFrame = CFrame.new(targetPos) * CFrame.Angles(0, ry, 0);
	self:RestoreCollisions();
	return true;
end;
Hub.GetVotePad = function(self, padName)
	local lobby = self:GetLobby();
	if lobby then
		local votePadsFolder = lobby:FindFirstChild("VotePads");
		if votePadsFolder then
			local p = votePadsFolder:FindFirstChild(padName);
			if p then
				return p;
			end
		end
		local direct = lobby:FindFirstChild(padName);
		if direct then
			return direct;
		end
		local rec = lobby:FindFirstChild(padName, true);
		if rec then
			return rec;
		end
	end
	return self.Services.Workspace:FindFirstChild(padName, true);
end;
