		img.Image = self.Maps.Cached[padName].Image;
		img.ScaleType = Enum.ScaleType.Crop;
		img.Parent = card;
		self:Corner(img, 6);
		local nameLbl = Instance.new("TextLabel");
		nameLbl.Name = "MapName";
		nameLbl.Position = UDim2.new(0, 6, 0, 88);
